from pathlib import Path

root = Path(__file__).resolve().parents[1]

# Fix the missing public route that caused the 404 from "Nouvelle demande".
app = root / "client/src/App.tsx"
s = app.read_text()
s = s.replace('    <Route path="/partenaires" component={Home} />\n', '    <Route path="/partenaires" component={Home} />\n    <Route path="/contact" component={Home} />\n')
app.write_text(s)

home = root / "client/src/pages/Home.tsx"
